messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #222; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10.0; // seconds
        const IDLE_TIME = 2.0;
        const WALK_TIME = 3.0;
        const RUN_TIME = 3.0;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 12); // Side-on view
        camera.lookAt(0, 1.2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.4 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.7 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.5 });
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });

        // --- Helper: Create Limb ---
        function createLimb(width, height, depth, material, pivotX, pivotY, pivotZ, rotX, rotY, rotZ) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mesh = new THREE.Mesh(geo, material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            // Create a pivot group to handle rotation at the joint
            const pivot = new THREE.Group();
            pivot.position.set(pivotX, pivotY, pivotZ);
            pivot.rotation.set(rotX, rotY, rotZ);

            // Offset geometry so the pivot is at the "top" of the limb (for limbs hanging down)
            mesh.position.y = -height / 2;

            pivot.add(mesh);
            return { mesh, pivot };
        }

        // --- Build Humanoid ---
        const humanoid = new THREE.Group();

        // 1. Torso
        const torsoGeo = new THREE.BoxGeometry(0.5, 0.7, 0.3);
        const torso = new THREE.Mesh(torsoGeo, shirtMat);
        torso.castShadow = true;
        torso.position.y = 1.35; // Center of mass roughly
        humanoid.add(torso);

        // 2. Head
        const headGeo = new THREE.BoxGeometry(0.35, 0.4, 0.35);
        const head = new THREE.Mesh(headGeo, skinMat);
        head.position.y = 1.95;
        head.castShadow = true;
        humanoid.add(head);

        // 3. Arms
        const armWidth = 0.15;
        const armHeight = 0.6;

        const leftArm = createLimb(armWidth, armHeight, armWidth, shirtMat, -0.35, 1.65, 0, 0, 0, 0);
        leftArm.pivot.rotation.z = 0.2; // Slight angle away from body
        humanoid.add(leftArm.pivot);

        const rightArm = createLimb(armWidth, armHeight, armWidth, shirtMat, 0.35, 1.65, 0, 0, 0, 0);
        rightArm.pivot.rotation.z = -0.2;
        humanoid.add(rightArm.pivot);

        // 4. Legs
        const legWidth = 0.18;
        const legHeight = 0.8;

        const leftLeg = createLimb(legWidth, legHeight, legWidth, pantsMat, -0.15, 1.0, 0, 0, 0, 0);
        humanoid.add(leftLeg.pivot);

        const rightLeg = createLimb(legWidth, legHeight, legWidth, pantsMat, 0.15, 1.0, 0, 0, 0, 0);
        humanoid.add(rightLeg.pivot);

        // 5. Feet (Visual only, attached to legs)
        const footGeo = new THREE.BoxGeometry(0.2, 0.1, 0.35);

        const leftFoot = new THREE.Mesh(footGeo, shoeMat);
        leftFoot.position.set(0, -legHeight/2, 0.1); // Slightly forward
        leftFoot.castShadow = true;
        leftLeg.mesh.add(leftFoot);

        const rightFoot = new THREE.Mesh(footGeo, shoeMat);
        rightFoot.position.set(0, -legHeight/2, 0.1);
        rightFoot.castShadow = true;
        rightLeg.mesh.add(rightFoot);

        scene.add(humanoid);

        // --- Treadmill / Ground ---
        const groundGeo = new THREE.BoxGeometry(4, 0.2, 6);
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Animation Logic ---

        // Helper to map value between ranges
        function mapRange(value, inMin, inMax, outMin, outMax) {
            return outMin + (value - inMin) * (outMax - outMin) / (inMax - inMin);
        }

        // Helper for smooth easing (Sine)
        function easeInOutSine(x) {
            return -(Math.cos(Math.PI * x) - 1) / 2;
        }

        // Animation State
        let time = 0;
        let lastTime = performance.now();

        // Pre-calculated animation parameters
        // Walking: ~1.5Hz (fastest normal walk)
        const walkFreq = 1.5; 
        // Running: ~3.0Hz (sprint)
        const runFreq = 3.0;

        function animate() {
            requestAnimationFrame(animate);

            const now = performance.now();
            const dt = (now - lastTime) / 1000;
            lastTime = now;

            time += dt;
            if (time > CYCLE_DURATION) time -= CYCLE_DURATION;

            // --- Determine Phase ---
            let phase = '';
            let phaseProgress = 0; // 0 to 1 within the phase

            if (time < IDLE_TIME) {
                phase = 'IDLE';
                phaseProgress = time / IDLE_TIME;
            } else if (time < IDLE_TIME + WALK_TIME) {
                phase = 'WALK';
                phaseProgress = (time - IDLE_TIME) / WALK_TIME;
            } else if (time < IDLE_TIME + WALK_TIME + RUN_TIME) {
                phase = 'RUN';
                phaseProgress = (time - IDLE_TIME - WALK_TIME) / RUN_TIME;
            } else {
                phase = 'IDLE';
                phaseProgress = (time - IDLE_TIME - WALK_TIME - RUN_TIME) / (CYCLE_DURATION - (IDLE_TIME + WALK_TIME + RUN_TIME));
            }

            // --- Calculate Angles ---
            let legAngle = 0;
            let armAngle = 0;
            let bodyLean = 0;
            let bodyBob = 0;

            if (phase === 'IDLE') {
                // Stand still (angles = 0)
                legAngle = 0;
                armAngle = 0;
                bodyLean = 0;
                bodyBob = 0;
            } 
            else if (phase === 'WALK') {
                // Walking Gait
                const speed = walkFreq;
                const angle = Math.sin(time * speed * Math.PI * 2) * 0.8; // +/- 0.8 radians (~45 deg)

                // Opposing limbs: Left Leg +, Right Leg -
                // Arms: Left Arm -, Right Arm + (opposite to legs)

                legAngle = angle;
                armAngle = -angle; // Opposite swing

                // Walking Bob: Up when legs are straight (0, PI), Down when crossed (PI/2)
                // Actually, bob is usually max at extremes of swing in simple models, 
                // or min at extremes. Let's do a subtle bob.
                bodyBob = Math.abs(Math.sin(time * speed * Math.PI * 2)) * 0.05;

                bodyLean = 0.05; // Slight forward lean
            } 
            else if (phase === 'RUN') {
                // Running Gait
                const speed = runFreq;
                const angle = Math.sin(time * speed * Math.PI * 2) * 1.2; // +/- 1.2 radians (~70 deg) - Larger swing

                legAngle = angle;
                armAngle = -angle; 

                // Running Bob: More pronounced
                bodyBob = Math.abs(Math.sin(time * speed * Math.PI * 2)) * 0.15;

                bodyLean = 0.3; // More forward lean
            }

            // --- Apply Transforms ---

            // 1. Legs (Knees should bend slightly when leg swings back to avoid clipping through ground)
            // Left Leg
            leftLeg.pivot.rotation.x = legAngle;
            // Simple knee bend: if leg is swinging back (negative angle), bend knee
            if (leftLeg.pivot.rotation.x < 0) {
                leftLeg.mesh.rotation.x = -Math.abs(leftLeg.pivot.rotation.x) * 0.5;
            } else {
                leftLeg.mesh.rotation.x = 0;
            }

            // Right Leg
            rightLeg.pivot.rotation.x = -legAngle; // Opposite
            if (rightLeg.pivot.rotation.x < 0) {
                rightLeg.mesh.rotation.x = -Math.abs(rightLeg.pivot.rotation.x) * 0.5;
            } else {
                rightLeg.mesh.rotation.x = 0;
            }

            // 2. Arms
            // Add a slight elbow bend for running realism
            leftArm.pivot.rotation.x = armAngle;
            if (leftArm.pivot.rotation.x > 0) { // If arm swings back
                leftArm.mesh.rotation.x = -0.5; // Bend elbow
            } else {
                leftArm.mesh.rotation.x = 0;
            }

            rightArm.pivot.rotation.x = -armAngle;
            if (rightArm.pivot.rotation.x > 0) {
                rightArm.mesh.rotation.x = -0.5;
            } else {
                rightArm.mesh.rotation.x = 0;
            }

            // 3. Body
            // Apply lean
            humanoid.rotation.z = -bodyLean; // Lean forward (negative Z rotation in this coord system depends on view, usually +Z is right, -Z is left. Forward lean is rotation around Z axis)
            // Wait, standard Three.js: X is right, Y is up, Z is out. 
            // Rotation around Z: Tipping forward/backward.
            // If camera is at +Z looking at origin, +Z rotation tips the object towards the camera (backwards lean).
            // -Z rotation tips it away (forward lean).

            // Apply Bob (Vertical translation)
            humanoid.position.y = 1.0 + bodyBob; // Base height is roughly hip height

            // Add a slight rotation to the torso for extra life (shoulders twist slightly)
            torso.rotation.y = Math.sin(time * 2) * 0.1;

            // --- Render ---
            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();

    </script>
</body>
</html>
```
